from griffe.loader import load


class DocstringCheckerExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_object_visited(self, obj):
        """Called when an object is visited during loading."""
        if obj.is_function:
            if obj.docstring:
                obj.docstring.value += " [checked]"


extensions = [DocstringCheckerExtension()]
package = load("mypkg", extensions=extensions)

